-- ============================================================
--  Organisaties aanvullen en contactpersonen uit de mail
--
--  Deel 1: soort en sector voor de 44 organisaties die die nog
--  niet hadden (het overzicht van 28 september 2026). Alleen lege
--  velden worden gevuld; wat al is ingevuld blijft staan.
--
--  Deel 2: de 77 regels uit "contactpersonen_mail.xlsx".
--  - Een persoon die er al is (zelfde e-mailadres of zelfde naam)
--    wordt niet dubbel aangemaakt; alleen lege velden (functie,
--    e-mail, telefoon, organisatie) worden aangevuld.
--  - Ben, Boudewijn en Klaas worden herkend bij MCN op voornaam.
--  - Organisaties die nog niet bestonden worden aangemaakt.
--  - Algemene adressen (info@, penningmeester@) komen bij de
--    organisatie, niet als persoon.
--  - Personen krijgen een veld "notitie" voor extra e-mailadressen
--    en opmerkingen.
--
--  Je mag dit opnieuw draaien: er ontstaan geen dubbelen.
--  Elke regel is een losse opdracht, zodat een afgekapte plak
--  gewoon invoegt wat er wél aankwam. Onderaan staat een telling.
-- ============================================================

alter table personen add column if not exists notitie text not null default '';

insert into organisatie_sectoren (naam, volgorde) values ('Overkoepelend', 60) on conflict (naam) do nothing;
insert into organisatie_sectoren (naam, volgorde) values ('Niet sectorgebonden', 70) on conflict (naam) do nothing;
insert into organisatie_soorten (naam, volgorde) values ('Leverancier', 60) on conflict (naam) do nothing;
insert into organisatie_soorten (naam, volgorde) values ('Bedrijf', 100) on conflict (naam) do nothing;
insert into organisatie_soorten (naam, volgorde) values ('Fonds', 50) on conflict (naam) do nothing;
insert into organisatie_soorten (naam, volgorde) values ('Overheid', 40) on conflict (naam) do nothing;
insert into organisatie_soorten (naam, volgorde) values ('Onderwijs of onderzoek', 80) on conflict (naam) do nothing;

