-- ── Deel 2b: algemene adressen bij bestaande organisaties ─────
update organisaties set notitie = case when notitie = '' then 'Voorzitter: voorzitter@ssrp.nl; bestuur: bestuur@ssrp.nl' else notitie || chr(10) || 'Voorzitter: voorzitter@ssrp.nl; bestuur: bestuur@ssrp.nl' end where lower(naam) = lower('SSRP') and position('Voorzitter: voorzitter@ssrp.nl; bestuur: bestuur@ssrp.nl' in notitie) = 0;
update organisaties set notitie = case when notitie = '' then 'Penningmeester: penningmeester@fehac.nl' else notitie || chr(10) || 'Penningmeester: penningmeester@fehac.nl' end where lower(naam) = lower('FEHAC') and position('Penningmeester: penningmeester@fehac.nl' in notitie) = 0;
