-- ── Deel 2c: personen (65) ─────────────────────────────────────
-- Per persoon twee opdrachten: eerst aanvullen als hij er al is,
-- dan toevoegen als hij er nog niet is.
-- Boudewijn Ridder
update personen set functie = case when functie = '' then 'Projectmanager' else functie end, email = case when email = '' then 'bridder@raafprojecten.nl' else email end, telefoon = case when telefoon = '' then '06-535 838 83' else telefoon end, organisatie_id = coalesce(organisatie_id, coalesce((select id from organisaties where eigen order by aangemaakt limit 1), (select id from organisaties where lower(naam) = 'stichting mobiele collectie nederland' limit 1))), notitie = case when 'Via RAAF Projecten' = '' or position('Via RAAF Projecten' in notitie) > 0 then notitie when notitie = '' then 'Via RAAF Projecten' else notitie || chr(10) || 'Via RAAF Projecten' end, voornaam = case when voornaam = '' then 'Boudewijn' else voornaam end, tussenvoegsel = case when achternaam = '' then '' else tussenvoegsel end, achternaam = case when achternaam = '' then 'Ridder' else achternaam end, naam = case when achternaam = '' then 'Boudewijn Ridder' else naam end where id = (select id from personen where lower(email) in ('bridder@raafprojecten.nl') or lower(naam) = lower('Boudewijn Ridder') or (organisatie_id = coalesce((select id from organisaties where eigen order by aangemaakt limit 1), (select id from organisaties where lower(naam) = 'stichting mobiele collectie nederland' limit 1)) and lower(trim(voornaam)) = 'boudewijn') order by aangemaakt limit 1);
insert into personen (id, organisatie_id, naam, voornaam, tussenvoegsel, achternaam, functie, email, telefoon, notitie) select 'pers-mail-boudewijn-ridder', coalesce((select id from organisaties where eigen order by aangemaakt limit 1), (select id from organisaties where lower(naam) = 'stichting mobiele collectie nederland' limit 1)), 'Boudewijn Ridder', 'Boudewijn', '', 'Ridder', 'Projectmanager', 'bridder@raafprojecten.nl', '06-535 838 83', 'Via RAAF Projecten' where not exists (select 1 from personen where lower(email) in ('bridder@raafprojecten.nl') or lower(naam) = lower('Boudewijn Ridder') or (organisatie_id = coalesce((select id from organisaties where eigen order by aangemaakt limit 1), (select id from organisaties where lower(naam) = 'stichting mobiele collectie nederland' limit 1)) and lower(trim(voornaam)) = 'boudewijn')) on conflict (id) do nothing;
-- Stefan Hulman
update personen set functie = case when functie = '' then 'Voorzitter' else functie end, email = case when email = '' then 'voorzitter@fehac.nl' else email end, telefoon = case when telefoon = '' then '085-303 46 51' else telefoon end, organisatie_id = coalesce(organisatie_id, (select id from organisaties where lower(naam) = lower('FEHAC') order by aangemaakt limit 1)), notitie = case when 'Waarschijnlijk ook stefan@firmcc.com' = '' or position('Waarschijnlijk ook stefan@firmcc.com' in notitie) > 0 then notitie when notitie = '' then 'Waarschijnlijk ook stefan@firmcc.com' else notitie || chr(10) || 'Waarschijnlijk ook stefan@firmcc.com' end, voornaam = case when voornaam = '' then 'Stefan' else voornaam end, tussenvoegsel = case when achternaam = '' then '' else tussenvoegsel end, achternaam = case when achternaam = '' then 'Hulman' else achternaam end, naam = case when achternaam = '' then 'Stefan Hulman' else naam end where id = (select id from personen where lower(email) in ('voorzitter@fehac.nl', 'stefan@firmcc.com') or lower(naam) = lower('Stefan Hulman') order by aangemaakt limit 1);
insert into personen (id, organisatie_id, naam, voornaam, tussenvoegsel, achternaam, functie, email, telefoon, notitie) select 'pers-mail-stefan-hulman', (select id from organisaties where lower(naam) = lower('FEHAC') order by aangemaakt limit 1), 'Stefan Hulman', 'Stefan', '', 'Hulman', 'Voorzitter', 'voorzitter@fehac.nl', '085-303 46 51', 'Waarschijnlijk ook stefan@firmcc.com' where not exists (select 1 from personen where lower(email) in ('voorzitter@fehac.nl', 'stefan@firmcc.com') or lower(naam) = lower('Stefan Hulman')) on conflict (id) do nothing;
