update personen set functie = case when functie = '' then '' else functie end, email = case when email = '' then 'ajongeneelen@hotmail.com' else email end, telefoon = case when telefoon = '' then '' else telefoon end, organisatie_id = coalesce(organisatie_id, null), notitie = case when '' = '' or position('' in notitie) > 0 then notitie when notitie = '' then '' else notitie || chr(10) || '' end, voornaam = case when voornaam = '' then 'A.' else voornaam end, tussenvoegsel = case when achternaam = '' then '' else tussenvoegsel end, achternaam = case when achternaam = '' then 'Jongeneelen' else achternaam end, naam = case when achternaam = '' then 'A. Jongeneelen' else naam end where id = (select id from personen where lower(email) in ('ajongeneelen@hotmail.com') or lower(naam) = lower('A. Jongeneelen') order by aangemaakt limit 1);
insert into personen (id, organisatie_id, naam, voornaam, tussenvoegsel, achternaam, functie, email, telefoon, notitie) select 'pers-mail-a-jongeneelen', null, 'A. Jongeneelen', 'A.', '', 'Jongeneelen', '', 'ajongeneelen@hotmail.com', '', '' where not exists (select 1 from personen where lower(email) in ('ajongeneelen@hotmail.com') or lower(naam) = lower('A. Jongeneelen')) on conflict (id) do nothing;
-- IJsbrand Dijkstra
update personen set functie = case when functie = '' then '' else functie end, email = case when email = '' then 'ijsbrand.dijkstra@xs4all.nl' else email end, telefoon = case when telefoon = '' then '' else telefoon end, organisatie_id = coalesce(organisatie_id, null), notitie = case when '' = '' or position('' in notitie) > 0 then notitie when notitie = '' then '' else notitie || chr(10) || '' end, voornaam = case when voornaam = '' then 'IJsbrand' else voornaam end, tussenvoegsel = case when achternaam = '' then '' else tussenvoegsel end, achternaam = case when achternaam = '' then 'Dijkstra' else achternaam end, naam = case when achternaam = '' then 'IJsbrand Dijkstra' else naam end where id = (select id from personen where lower(email) in ('ijsbrand.dijkstra@xs4all.nl') or lower(naam) = lower('IJsbrand Dijkstra') order by aangemaakt limit 1);
insert into personen (id, organisatie_id, naam, voornaam, tussenvoegsel, achternaam, functie, email, telefoon, notitie) select 'pers-mail-ijsbrand-dijkstra', null, 'IJsbrand Dijkstra', 'IJsbrand', '', 'Dijkstra', '', 'ijsbrand.dijkstra@xs4all.nl', '', '' where not exists (select 1 from personen where lower(email) in ('ijsbrand.dijkstra@xs4all.nl') or lower(naam) = lower('IJsbrand Dijkstra')) on conflict (id) do nothing;

-- ── Controle ────────────────────────────────────────────────
-- Verwacht: nog maar een handvol organisaties zonder sector
-- (de nieuwe waarvan de soort onbekend is), en zo'n 60 personen
-- meer dan vóór het draaien.
select 'organisaties' as wat, count(*) from organisaties
union all select 'waarvan zonder sector', count(*) from organisaties where sector = ''
union all select 'personen', count(*) from personen
union all select 'personen uit de mail', count(*) from personen where id like 'pers-mail-%'
union all select 'personen met notitie', count(*) from personen where notitie <> '';
